// Файл сгенерирован: node ai-notify/build-worker-assets.mjs — руками не править.
export const AI_NOTIFY_HTML = "<!doctype html>\n<html lang=\"ru\">\n<head>\n<meta charset=\"utf-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n<title>ИИ-напоминания клиентам — воркшоп</title>\n<meta name=\"description\" content=\"Интерактивный разбор для воркшопа: стек каналов, связка уведомлений в несколько волн, три причины подключать ИИ, 10 CJM по нишам и мини-игра «стань клиентом».\">\n<link rel=\"preconnect\" href=\"https://fonts.googleapis.com\">\n<link rel=\"preconnect\" href=\"https://fonts.gstatic.com\" crossorigin>\n<link href=\"https://fonts.googleapis.com/css2?family=Golos+Text:wght@400;500;600;700&family=IBM+Plex+Mono:wght@400;500;600&display=swap\" rel=\"stylesheet\">\n<style>\n:root{\n  --bg:#F3F4F7; --card:#FFFFFF; --line:#E3E6EE; --line-soft:#EFF1F6; --sunk:#F7F8FB;\n  --ink:#101828; --ink-2:#525B6E; --ink-3:#8A93A6;\n  --brand:#2B4ACB; --brand-soft:#E9EDFC; --brand-ink:#1F38A0;\n  --good:#12805C; --good-soft:#E4F3ED;\n  --bad:#C4373C; --bad-soft:#FBEAEA;\n  --warn:#B7791F; --warn-soft:#FBF1DF;\n  --alt:#5B4BD6; --alt-soft:#EDEBFB;\n  --teal:#0E7C86; --teal-soft:#E2F1F2;\n  --r-lg:12px; --r:9px; --r-sm:6px;\n  --shadow:0 1px 2px rgba(16,24,40,.05);\n  --shadow-pop:0 24px 64px rgba(16,24,40,.18);\n  --sans:'Golos Text',-apple-system,BlinkMacSystemFont,'Segoe UI',Roboto,Arial,sans-serif;\n  --mono:'IBM Plex Mono',ui-monospace,SFMono-Regular,Menlo,monospace;\n}\n*{box-sizing:border-box}\nhtml{-webkit-text-size-adjust:100%;scroll-behavior:smooth}\nbody{margin:0;background:var(--bg);color:var(--ink);font-family:var(--sans);font-size:14px;line-height:1.5;-webkit-font-smoothing:antialiased}\nh1,h2,h3,h4{margin:0;font-weight:600;letter-spacing:-.01em}\np{margin:0}\nbutton{font:inherit;color:inherit}\na{color:var(--brand)}\n.wrap{max-width:1180px;margin:0 auto;padding:0 24px}\n@media(max-width:560px){.wrap{padding:0 16px}}\n.num{font-family:var(--mono);font-variant-numeric:tabular-nums;letter-spacing:-.02em}\n\n/* hero */\n.hero{padding:44px 0 40px}\n.hero .kicker{display:inline-flex;align-items:center;gap:7px;font-size:11.5px;font-weight:600;letter-spacing:.02em;text-transform:uppercase;\n  color:var(--brand);background:var(--brand-soft);padding:5px 11px;border-radius:999px;margin-bottom:16px}\n.hero h1{font-size:34px;max-width:760px;letter-spacing:-.02em}\n.hero p.lead{margin-top:14px;max-width:640px;color:var(--ink-2);font-size:15.5px}\n.hero .stats{display:flex;gap:28px;margin-top:28px;flex-wrap:wrap}\n.hero .stats div span{display:block;color:var(--ink-3);font-size:12px}\n.hero .stats div b{font-family:var(--mono);font-size:20px;font-weight:600}\n\n/* sections */\nsection{padding-top:44px}\n.sec-head{margin-bottom:16px;max-width:780px}\n.sec-head h2{font-size:22px}\n.sec-head p{margin-top:8px;color:var(--ink-2);font-size:14px}\n.card{background:var(--card);border:1px solid var(--line);border-radius:var(--r-lg)}\n.card-pad{padding:20px 22px}\n.grid{display:grid;gap:14px}\n.grid > *{min-width:0}\n.g-2{grid-template-columns:repeat(2,1fr)}\n.g-3{grid-template-columns:repeat(3,1fr)}\n@media(max-width:900px){.g-2,.g-3{grid-template-columns:1fr}}\n\n/* channel badges */\n.chan{display:inline-flex;align-items:center;gap:6px;font-family:var(--mono);font-size:11.5px;font-weight:600;\n  padding:3px 9px;border-radius:var(--r-sm);white-space:nowrap}\n.chan i{width:6px;height:6px;border-radius:50%;background:currentColor}\n.chan.tg{background:var(--brand-soft);color:var(--brand-ink)}\n.chan.email{background:var(--teal-soft);color:var(--teal)}\n.chan.vk{background:var(--alt-soft);color:var(--alt)}\n.chan.max{background:var(--warn-soft);color:var(--warn)}\n.chan.sms{background:var(--bad-soft);color:var(--bad)}\n.chan.human{background:var(--line-soft);color:var(--ink-2)}\n\n/* channel table */\n.tbl-wrap{overflow-x:auto}\ntable.chtable{width:100%;border-collapse:collapse;font-size:13.5px}\ntable.chtable th{text-align:left;font-weight:500;color:var(--ink-3);font-size:11.5px;text-transform:uppercase;letter-spacing:.02em;\n  padding:0 14px 10px 0;border-bottom:1px solid var(--line)}\ntable.chtable td{text-align:left;padding:14px 14px 14px 0;border-bottom:1px solid var(--line-soft);vertical-align:top}\ntable.chtable tr:last-child td{border-bottom:none}\ntable.chtable td.ch-name{font-weight:600;white-space:nowrap}\ntable.chtable td.ch-name small{display:block;font-weight:400;color:var(--ink-3);font-size:12px;margin-top:2px}\n.badge{display:inline-flex;align-items:center;font-family:var(--mono);font-size:11.5px;font-weight:600;padding:3px 9px;border-radius:var(--r-sm);white-space:nowrap}\n.badge.g{background:var(--good-soft);color:var(--good)}\n.badge.a{background:var(--warn-soft);color:var(--warn)}\n.badge.r{background:var(--bad-soft);color:var(--bad)}\n.badge.n{background:var(--line-soft);color:var(--ink-2)}\n\n/* cascade */\n.cascade{display:flex;align-items:stretch;gap:0;overflow-x:auto;padding-bottom:6px}\n.casc-step{flex:1 1 220px;min-width:200px;background:var(--card);border:1px solid var(--line);border-radius:var(--r-lg);padding:16px 18px;position:relative}\n.casc-step .n{font-family:var(--mono);font-size:11px;color:var(--ink-3);margin-bottom:8px}\n.casc-step h4{font-size:14.5px;margin-bottom:6px}\n.casc-step p{color:var(--ink-2);font-size:12.5px}\n.casc-arrow{flex:0 0 auto;display:flex;align-items:center;justify-content:center;width:34px;color:var(--ink-3);font-size:18px}\n.casc-bad{margin-top:14px;padding:14px 18px;border-radius:var(--r);background:var(--bad-soft);color:var(--bad-ink,#8f2a2e);font-size:13px;border:1px dashed var(--bad)}\n\n/* insight-style cards (why AI) */\n.ins{display:grid;gap:14px;grid-template-columns:repeat(3,1fr)}\n@media(max-width:980px){.ins{grid-template-columns:1fr}}\n.insight{padding:19px 20px;display:flex;flex-direction:column;gap:11px}\n.insight .tag{align-self:flex-start;display:inline-flex;align-items:center;gap:7px;font-size:11.5px;font-weight:600;\n  padding:3px 9px 3px 7px;border-radius:var(--r-sm);background:var(--line-soft);color:var(--ink-2)}\n.insight .tag b{width:6px;height:6px;border-radius:50%;background:currentColor}\n.insight.n1 .tag{background:var(--bad-soft);color:var(--bad)}\n.insight.n2 .tag{background:var(--warn-soft);color:var(--warn)}\n.insight.n3 .tag{background:var(--good-soft);color:var(--good)}\n.insight h4{font-size:15.5px;font-weight:600;line-height:1.35}\n.insight p{color:var(--ink-2);font-size:13.5px}\n.msgbox{background:var(--sunk);border:1px solid var(--line-soft);border-radius:var(--r);padding:11px 13px;font-size:13px;line-height:1.5}\n.msgbox b{color:var(--ink)}\n.insight .foot{margin-top:auto;padding-top:10px;border-top:1px solid var(--line-soft);font-size:12.5px;color:var(--ink-3)}\n.insight .foot a{font-weight:600}\n\n/* cjm tabs */\n.cjm-layout{display:grid;grid-template-columns:220px 1fr;gap:18px}\n@media(max-width:860px){.cjm-layout{grid-template-columns:1fr}}\n.cjm-tabs{display:flex;flex-direction:column;gap:3px}\n.cjm-tabs button{text-align:left;border:1px solid transparent;background:transparent;border-radius:var(--r);padding:9px 12px;font-size:13px;color:var(--ink-2);cursor:pointer}\n.cjm-tabs button:hover{background:var(--sunk)}\n.cjm-tabs button.on{background:var(--card);border-color:var(--line);color:var(--ink);font-weight:600;box-shadow:var(--shadow)}\n.cjm-tabs button small{display:block;font-weight:400;color:var(--ink-3);font-size:11.5px;margin-top:1px}\n@media(max-width:860px){.cjm-tabs{flex-direction:row;overflow-x:auto;flex-wrap:nowrap}.cjm-tabs button{white-space:nowrap}.cjm-tabs button small{display:none}}\n\n.cjm-head{display:flex;align-items:flex-start;gap:14px;margin-bottom:16px;flex-wrap:wrap}\n.cjm-avatar{width:44px;height:44px;border-radius:50%;background:var(--brand);color:#fff;display:grid;place-items:center;font-weight:600;font-size:16px;flex:none}\n.cjm-head h3{font-size:16.5px}\n.cjm-head .who{color:var(--ink-3);font-size:12.5px;margin-top:2px}\n.cjm-head .pain{margin-top:6px;font-size:13px;color:var(--ink-2);max-width:520px}\n.cjm-outcome{margin-left:auto}\n\n.timeline{display:flex;flex-direction:column}\n.tl-step{display:grid;grid-template-columns:100px 22px 1fr;gap:0 14px;position:relative}\n.tl-step .t{font-family:var(--mono);font-size:11.5px;color:var(--ink-3);padding-top:2px;white-space:nowrap}\n.tl-dot-col{display:flex;flex-direction:column;align-items:center}\n.tl-dot{width:9px;height:9px;border-radius:50%;background:var(--brand);flex:none;margin-top:5px}\n.tl-line{width:1px;flex:1;background:var(--line);margin-top:2px}\n.tl-step:last-child .tl-line{display:none}\n.tl-body{padding-bottom:20px}\n.tl-body .row1{display:flex;align-items:center;gap:8px;margin-bottom:6px;flex-wrap:wrap}\n.tl-body .msg{color:var(--ink);font-size:13.5px;line-height:1.5}\n.tl-body .why{color:var(--ink-3);font-size:12px;margin-top:5px}\n@media(max-width:520px){.tl-step{grid-template-columns:70px 18px 1fr}}\n\n/* pros/cons */\n.pc-card h3{font-size:15px;margin-bottom:3px}\n.pc-card .sub{color:var(--ink-3);font-size:12px;margin-bottom:14px}\n.pc-list{list-style:none;margin:0 0 14px;padding:0;display:flex;flex-direction:column;gap:8px}\n.pc-list li{display:flex;gap:9px;font-size:13px;color:var(--ink-2);line-height:1.4}\n.pc-list li i{flex:none;width:17px;height:17px;border-radius:5px;display:grid;place-items:center;font-style:normal;font-size:11px;font-weight:700;margin-top:1px}\n.pc-list.plus li i{background:var(--good-soft);color:var(--good)}\n.pc-list.minus li i{background:var(--bad-soft);color:var(--bad)}\n.pc-card.mid{border-color:var(--brand);box-shadow:0 0 0 1px var(--brand) inset}\n\n/* trends */\n.trend-col h3{display:flex;align-items:center;gap:9px;font-size:15.5px;margin-bottom:14px}\n.trend-col h3 .flag{font-family:var(--mono);font-size:11px;font-weight:700;padding:3px 8px;border-radius:var(--r-sm)}\n.trend-col.ru h3 .flag{background:var(--brand-soft);color:var(--brand-ink)}\n.trend-col.intl h3 .flag{background:var(--alt-soft);color:var(--alt)}\n.trend-list{list-style:none;margin:0;padding:0;display:flex;flex-direction:column;gap:13px}\n.trend-list li{font-size:13.5px;color:var(--ink-2);line-height:1.5;padding-left:16px;position:relative}\n.trend-list li::before{content:'';position:absolute;left:0;top:7px;width:6px;height:6px;border-radius:50%;background:var(--ink-3)}\n.trend-list li b{color:var(--ink);font-weight:600}\n\n/* game */\n.game-wrap{display:grid;grid-template-columns:1fr 260px;gap:18px}\n@media(max-width:860px){.game-wrap{grid-template-columns:1fr}}\n.game-persona{display:flex;align-items:center;gap:12px;margin-bottom:16px}\n.game-persona .ava{width:46px;height:46px;border-radius:50%;background:var(--alt);color:#fff;display:grid;place-items:center;font-weight:700;font-size:17px;flex:none}\n.game-persona h3{font-size:16px}\n.game-persona .sub{color:var(--ink-3);font-size:12.5px;margin-top:1px}\n.game-scene{font-size:14.5px;line-height:1.6;color:var(--ink)}\n.game-scene .meta{display:flex;gap:10px;align-items:center;margin-bottom:10px;flex-wrap:wrap}\n.game-meta-tag{font-family:var(--mono);font-size:11px;color:var(--ink-3)}\n.game-msg{margin-top:12px}\n.game-choices{margin-top:20px;display:flex;flex-direction:column;gap:9px}\n.choice-btn{text-align:left;border:1px solid var(--line);background:var(--card);border-radius:var(--r);padding:12px 14px;cursor:pointer;font-size:13.5px;color:var(--ink);\n  display:flex;gap:10px;align-items:flex-start;transition:border-color .12s,background .12s}\n.choice-btn:hover{border-color:var(--brand);background:var(--brand-soft)}\n.choice-btn .letter{font-family:var(--mono);font-weight:700;color:var(--brand);flex:none}\n.choice-btn.reveal{cursor:default;background:var(--sunk)}\n.choice-btn.reveal:hover{border-color:var(--line);background:var(--sunk)}\n.game-next{margin-top:20px}\n.game-next button{border:1px solid var(--brand);background:var(--brand);color:#fff;border-radius:var(--r);padding:10px 20px;font-size:13.5px;font-weight:600;cursor:pointer}\n.game-next button:hover{background:var(--brand-ink)}\n.reaction-box{margin-top:16px;background:var(--sunk);border:1px solid var(--line-soft);border-radius:var(--r);padding:13px 15px;font-size:13px;color:var(--ink-2);line-height:1.5}\n.reaction-box b{color:var(--ink)}\n\n.game-side{display:flex;flex-direction:column;gap:14px}\n.heat-card{padding:16px 17px}\n.heat-card .lab{font-size:12px;color:var(--ink-3);margin-bottom:8px}\n.heat-track{height:8px;border-radius:4px;background:var(--line-soft);overflow:hidden}\n.heat-track > i{display:block;height:100%;border-radius:4px;transition:width .35s ease, background .35s ease}\n.heat-word{margin-top:8px;font-weight:600;font-size:14px}\n.progress-card{padding:16px 17px}\n.progress-card .lab{font-size:12px;color:var(--ink-3);margin-bottom:8px}\n.step-dots{display:flex;flex-wrap:wrap;gap:5px}\n.step-dots i{width:7px;height:7px;border-radius:50%;background:var(--line);display:block}\n.step-dots i.done{background:var(--brand)}\n.restart-btn{border:1px solid var(--line);background:var(--card);border-radius:var(--r);padding:9px 14px;font-size:12.5px;color:var(--ink-2);cursor:pointer;width:100%}\n.restart-btn:hover{border-color:#CDD3E1;color:var(--ink)}\n\n.ending-banner{padding:22px;border-radius:var(--r-lg);margin-top:2px}\n.ending-banner.good{background:var(--good-soft);border:1px solid #B9E4D2}\n.ending-banner.mid{background:var(--warn-soft);border:1px solid #F0DCA8}\n.ending-banner.bad{background:var(--bad-soft);border:1px solid #F3C4C6}\n.ending-banner h4{font-size:16px;margin-bottom:8px}\n.ending-banner.good h4{color:var(--good)}\n.ending-banner.mid h4{color:var(--warn)}\n.ending-banner.bad h4{color:var(--bad)}\n.ending-banner p{font-size:13.5px;color:var(--ink-2);line-height:1.55}\n.ending-banner .lesson{margin-top:12px;padding-top:12px;border-top:1px solid rgba(16,24,40,.08);font-size:13px;color:var(--ink)}\n\nfooter{margin:50px 0 60px;color:var(--ink-3);font-size:12.5px;border-top:1px solid var(--line);padding-top:20px}\n</style>\n</head>\n<body>\n\n<main class=\"wrap\">\n\n  <section class=\"hero\" id=\"hero\">\n    <div class=\"kicker\">ИИ-напоминания клиентам</div>\n    <h1>ИИ сам решает, когда и что написать клиенту, который потерялся, забыл или ещё думает</h1>\n    <p class=\"lead\">Без ИИ это одна и та же рассылка всем подряд, без учёта момента и истории конкретного человека. С ИИ момент, формулировку и связку каналов каждый раз подбирают под конкретного клиента — и каналы при этом работают не по одному строго друг за другом, а несколькими волнами, вместе и по несколько раз. Разбираем на пяти каналах, десяти нишах и одной живой игре.</p>\n    <div class=\"stats\">\n      <div><span>Каналов в стеке</span><b>5</b></div>\n      <div><span>Примеров CJM</span><b>10</b></div>\n      <div><span>Этапов в игре</span><b>20</b></div>\n      <div><span>Каналов в одной волне</span><b class=\"num\">2–3</b></div>\n    </div>\n  </section>\n\n  <section id=\"channels\">\n    <div class=\"sec-head\">\n      <h2>Telegram, VK, Max, email, SMS — и всё</h2>\n      <p>WhatsApp и Instagram сознательно вне контура: в текущих условиях нет рабочего Business API на разумных условиях. Остаются пять каналов для связи с клиентом — и с точки зрения интеграции они совсем не равнозначны.</p>\n    </div>\n    <div class=\"card card-pad\">\n      <div class=\"tbl-wrap\">\n        <table class=\"chtable\">\n          <thead><tr><th>Канал</th><th>Как подключить</th><th>Сложность</th><th>Место в связке</th></tr></thead>\n          <tbody id=\"chBody\"></tbody>\n        </table>\n      </div>\n    </div>\n  </section>\n\n  <section id=\"cascade\">\n    <div class=\"sec-head\">\n      <h2>Каналы работают связкой, а не по одному</h2>\n      <p>Разные каналы не ждут очереди друг за другом — они срабатывают парами и тройками одновременно, и такая связка повторяется несколько раз, если клиент молчит. На каждой волне меняется не набор каналов, а содержание: сначала лёгкое напоминание, затем персональная рекомендация, затем стимул или дедлайн.</p>\n    </div>\n    <div class=\"cascade\" id=\"cascadeRow\"></div>\n    <div class=\"casc-bad\">Так делать не надо: закинуть один и тот же обезличенный текст сразу во все пять каналов один раз и на этом остановиться. Дело не в количестве каналов в связке, а в том, меняется ли содержание от волны к волне и умеет ли рассылка вовремя остановиться.</div>\n  </section>\n\n  <section id=\"why-ai\">\n    <div class=\"sec-head\">\n      <h2>Три примера, где ИИ сам пишет клиенту</h2>\n      <p>Каждый раз ИИ сам решает момент, формулировку и связку каналов — и пишет клиенту напрямую.</p>\n    </div>\n    <div class=\"ins\" id=\"whyAiGrid\"></div>\n  </section>\n\n  <section id=\"cjm\">\n    <div class=\"sec-head\">\n      <h2>10 CJM: одна и та же логика, разные клиенты</h2>\n      <p>Переключайте нишу — увидите путь конкретного человека: что он сделал, что написал ИИ, какой связкой каналов и почему именно так.</p>\n    </div>\n    <div class=\"cjm-layout\">\n      <div class=\"cjm-tabs\" id=\"cjmTabs\"></div>\n      <div class=\"card card-pad\" id=\"cjmPane\"></div>\n    </div>\n  </section>\n\n  <section id=\"game\">\n    <div class=\"sec-head\">\n      <h2>Побудьте клиентом сами</h2>\n      <p>Один из примеров выше — разбор «спортивная медицина, консультация по колену» — целиком в ролевом формате. На каждом шаге вы выбираете, что делает клиент, и видите, что происходит дальше.</p>\n    </div>\n    <div class=\"card card-pad\">\n      <div class=\"game-persona\">\n        <div class=\"ava\">ДВ</div>\n        <div>\n          <h3>Дмитрий Волков, 34 года</h3>\n          <div class=\"sub\">Менеджер по продажам в IT-дистрибьюторе · готовится к первому полумарафону · клиника «ДвижениеPRO»</div>\n        </div>\n      </div>\n      <div class=\"game-wrap\">\n        <div>\n          <div class=\"game-scene\" id=\"gameScene\"></div>\n        </div>\n        <div class=\"game-side\">\n          <div class=\"card heat-card\">\n            <div class=\"lab\">Температура клиента</div>\n            <div class=\"heat-track\"><i id=\"heatBar\"></i></div>\n            <div class=\"heat-word\" id=\"heatWord\"></div>\n          </div>\n          <div class=\"card progress-card\">\n            <div class=\"lab\">Шагов пройдено: <span id=\"stepCount\">0</span></div>\n            <div class=\"step-dots\" id=\"stepDots\"></div>\n          </div>\n          <button class=\"restart-btn\" id=\"restartBtn\">↺ Начать заново</button>\n        </div>\n      </div>\n    </div>\n  </section>\n\n  <section id=\"proscons\">\n    <div class=\"sec-head\">\n      <h2>Разовые vs системные vs ИИ-напоминания клиентам</h2>\n      <p>У каждого подхода есть своя область, где он оправдан — вопрос не «что лучше», а «где именно вы теряете клиентов сейчас».</p>\n    </div>\n    <div class=\"grid g-3\" id=\"pcGrid\"></div>\n  </section>\n\n  <section id=\"trends\">\n    <div class=\"sec-head\">\n      <h2>Что сейчас реально работает</h2>\n      <p>Отдельно — то, что заметно в рунет-практике, отдельно — то, что задаёт тон в зарубежных CRM-платформах. Полезно держать в голове обе картины: инструменты приходят оттуда, ограничения — свои.</p>\n    </div>\n    <div class=\"grid g-2\">\n      <div class=\"card card-pad trend-col ru\">\n        <h3><span class=\"flag\">RU</span> Рунет-практика</h3>\n        <ul class=\"trend-list\" id=\"trendRu\"></ul>\n      </div>\n      <div class=\"card card-pad trend-col intl\">\n        <h3><span class=\"flag\">INTL</span> Зарубежные платформы</h3>\n        <ul class=\"trend-list\" id=\"trendIntl\"></ul>\n      </div>\n    </div>\n  </section>\n\n  <footer>\n    <div>Материал для воркшопа CMO-сообщества · страница /ai-notify</div>\n  </footer>\n</main>\n\n<script>\n/* ===================== ДАННЫЕ: КАНАЛЫ ===================== */\nconst CHANNELS = [\n  { name:'Telegram', chan:'tg', how:'Нативный модуль в Zapier/Make, готовые триггеры бота', diff:'g', diffLabel:'Легко', role:'Почти в каждой волне — быстро, дёшево, высокая открываемость' },\n  { name:'Email', chan:'email', how:'Нативная интеграция в Zapier/Make через сервисы рассылок', diff:'g', diffLabel:'Легко', role:'Идёт в паре с мессенджером — для развёрнутого сообщения без давления' },\n  { name:'VK', chan:'vk', how:'Обычно HTTP-запросы или отдельный модуль к API сообщества, готовых блоков в Zapier/Make почти нет', diff:'a', diffLabel:'Средне', role:'Хорошо заходит в связке, если клиент реально живёт в сообществе бренда' },\n  { name:'Max', chan:'max', how:'Нет нативной интеграции нигде — только вебхуки или сторонние сервисы вроде BotHelp', diff:'r', diffLabel:'Сложно', role:'Закладывать время на разработку — аудитория уже переезжает сюда' },\n  { name:'SMS', chan:'sms', how:'Отдельный SMS-шлюз, не через Zapier напрямую', diff:'a', diffLabel:'Нужен провайдер', role:'Обычно в паре на финальной волне — дорого, но открываемость выше всех' },\n];\n\nfunction renderChannels(){\n  const body = document.getElementById('chBody');\n  body.innerHTML = CHANNELS.map(c => `\n    <tr>\n      <td class=\"ch-name\"><span class=\"chan ${c.chan}\"><i></i>${c.name}</span></td>\n      <td>${c.how}</td>\n      <td><span class=\"badge ${c.diff}\">${c.diffLabel}</span></td>\n      <td>${c.role}</td>\n    </tr>`).join('');\n}\n\n/* ===================== СВЯЗКИ КАНАЛОВ ПО ВОЛНАМ ===================== */\nconst CASCADE = [\n  { n:'Волна 1 · день 0', chans:[['tg','Telegram'],['email','Email']], text:'Лёгкое персональное напоминание сразу после события — оба канала уходят одновременно, без давления.' },\n  { n:'Волна 2 · тишина 2 дня', chans:[['tg','Telegram'],['sms','SMS']], text:'Та же связка повторяется, но сообщение конкретнее: персональная рекомендация или свободный слот.' },\n  { n:'Волна 3 · тишина ещё несколько дней', chans:[['sms','SMS'],['vk','VK']], text:'Финальная волна — конкретный стимул или дедлайн, самая заметная пара каналов.' },\n  { n:'Пауза', chans:[], text:'Если реакции нет ни на одной волне, новые волны прекращаются — клиент уходит в редкую рассылку вместо постоянного давления.' },\n];\n\nfunction renderCascade(){\n  const row = document.getElementById('cascadeRow');\n  let html = '';\n  CASCADE.forEach((s,i) => {\n    const badges = s.chans.map(([chan,label]) => `<span class=\"chan ${chan}\"><i></i>${label}</span>`).join(' + ');\n    html += `<div class=\"casc-step\"><div class=\"n\">${s.n}</div><h4>${badges || 'Тишина'}</h4><p>${s.text}</p></div>`;\n    if (i < CASCADE.length - 1) html += `<div class=\"casc-arrow\">→</div>`;\n  });\n  row.innerHTML = html;\n}\n\n/* ===================== ЗАЧЕМ ИИ: 3 ПРИМЕРА ===================== */\nconst WHY_AI = [\n  {\n    cls:'n1', tag:'Молчание клиента', title:'Страховая: связка SMS + Telegram вместо стандартного «напоминаем о себе»',\n    body:'Ирина посчитала КАСКО на Hyundai Creta на сайте «СтраховкаPRO» и ушла без оформления. Больше суток тишины — ИИ не шлёт «вы нас забыли», а одновременно в SMS и Telegram присылает её же расчёт. Если тишина повторяется — та же связка приходит снова, уже с дедлайном.',\n    msg:'«Ирина, вы считали КАСКО на Creta — вариант с франшизой 15 000 ₽ вышел 34 900 ₽/год. Ставка держится ещё 2 дня»',\n    foot:'Момент, машина и цифра — её собственные. Подробный разбор — в блоке 10 CJM →'\n  },\n  {\n    cls:'n2', tag:'Брошенная заявка', title:'«Брошенная корзина» в клиентской базе: не скидка в лоб, а конкретный слот',\n    body:'Дмитрий оставил заявку на консультацию по колену и пропал. Сообщение собирается из истории конкретного человека, а не шаблона «мы вас ждём», и уходит сразу в двух каналах, чтобы не зависеть от одного.',\n    msg:'«Дмитрий, ваш вопрос по колену не потерялся — за него отвечает врач Анна Ковалёва. Слот завтра в 11:00 всё ещё свободен»',\n    foot:'Это тот самый пример — пройдите его целиком как игру ↓'\n  },\n  {\n    cls:'n3', tag:'Связка каналов', title:'Несколько каналов вместе, а не по одному — и волна повторяется',\n    body:'Павел досмотрел вебинар «Skill Lab» и не купил поток. Ему пишут не в одном канале по кругу, а связкой из двух сразу — и если тишина, та же связка возвращается ещё раз с более сильным поводом.',\n    msg:'Волна 1: Telegram + Email — напоминание и персональная рекомендация по модулю → волна 2 (тишина 3 дня): Telegram + SMS — скидка со сроком в последний день',\n    foot:'Полный путь Павла — в блоке 10 CJM, ниша «Онлайн-школа» →'\n  },\n];\n\nfunction renderWhyAi(){\n  const grid = document.getElementById('whyAiGrid');\n  grid.innerHTML = WHY_AI.map(w => `\n    <div class=\"card insight ${w.cls}\">\n      <span class=\"tag\"><b></b>${w.tag}</span>\n      <h4>${w.title}</h4>\n      <p>${w.body}</p>\n      <div class=\"msgbox\">${w.msg}</div>\n      <div class=\"foot\">${w.foot}</div>\n    </div>`).join('');\n}\n\n/* ===================== 10 CJM ПО НИШАМ ===================== */\n/* Каждый шаг timeline — это волна: один или несколько каналов, отправленных одновременно.\n   Если клиент молчит, волна повторяется — с другим содержанием, но часто той же связкой каналов. */\nconst CJM = [\n  {\n    id:'insurance', niche:'Страхование', avatar:'ИС', name:'Ирина Смирнова, 41', who:'Клиентка · «СтраховкаPRO» · КАСКО на Hyundai Creta',\n    pain:'Посчитала три варианта франшизы на калькуляторе сайта, самый выгодный не оформила и закрыла вкладку.',\n    outcome:'g', outcomeLabel:'Оформила',\n    steps:[\n      {t:'День 0, 14:20', chans:[['human','Сайт']], msg:'Посчитала КАСКО с франшизой 15 000 ₽ — 34 900 ₽/год. Не оформила.', why:'Событие «калькулятор без оформления» уходит в CRM с тегом «тёплый клиент».'},\n      {t:'День 1, 19:40', chans:[['tg','Telegram'],['email','Email']], msg:'Волна 1, одновременно: «Ирина, вы считали КАСКО на Creta — вариант 34 900 ₽/год ещё держится 2 дня» — в Telegram коротко, в письме та же цифра с разбивкой по рискам.', why:'Два канала сразу увеличивают шанс, что она увидит хотя бы один — тексты синхронизированы, а не дублируют друг друга дословно.'},\n      {t:'День 1, 19:41', chans:[['human','Реакция']], msg:'Открыла оба, не ответила ни в одном.', why:'Открытие есть, действия нет — сигнал для более настойчивой волны.'},\n      {t:'День 3, 09:15', chans:[['sms','SMS'],['tg','Telegram']], msg:'Волна 2, та же связка: «Ставка 34 900 ₽ на Creta закреплена до завтра 18:00. Оформить: [ссылка]»', why:'Повторили связку из тех же двух каналов, но добавили конкретный дедлайн вместо общего напоминания.'},\n      {t:'День 3, 09:50', chans:[['human','Итог']], msg:'Перешла по ссылке из SMS и оформила онлайн.', why:'Сработала конкретика и дедлайн, а не факт повторного напоминания сам по себе.'},\n    ]\n  },\n  {\n    id:'dental', niche:'Стоматология', avatar:'СН', name:'Сергей Найденов, 45', who:'Клиент · «Белая Улыбка» · имплантация 2 зубов',\n    pain:'Посчитал стоимость имплантации (187 000 ₽), испугался цены и ушёл с сайта.',\n    outcome:'g', outcomeLabel:'Записался',\n    steps:[\n      {t:'День 0', chans:[['human','Сайт']], msg:'Рассчитал стоимость имплантации, форму «хочу консультацию» не заполнил, оставил только телефон в чате.', why:'Клиент «горячий по интересу, холодный по цене» — типичная причина отвала в стоматологии.'},\n      {t:'День 1', chans:[['tg','Telegram'],['email','Email']], msg:'Волна 1, одновременно: «При рассрочке имплантация — от 15 600 ₽/мес» в Telegram + развёрнутое письмо с разбивкой по этапам лечения и похожим кейсом пациента.', why:'ИИ сразу меняет рамку: не «187 000 ₽», а посильный ежемесячный платёж — сразу в двух форматах, коротком и подробном.'},\n      {t:'День 4', chans:[['vk','VK'],['tg','Telegram']], msg:'Волна 2, тишина 3 дня — связка повторяется: личное сообщение от имени врача во VK с приглашением на бесплатную консультацию с 3D-снимком + короткое Telegram-напоминание в тот же день.', why:'Он активно лайкал посты клиники во VK — этот канал добавили в волну, потому что там он реально проводит время.'},\n      {t:'День 4, вечер', chans:[['human','Итог']], msg:'Записался после VK-сообщения.', why:'Сработала связка «личный тон + канал, где человек реально сидит», а не единственный формальный email.'},\n    ]\n  },\n  {\n    id:'sportmed', niche:'Спортивная медицина', avatar:'ДВ', name:'Дмитрий Волков, 34', who:'Клиент · «ДвижениеPRO» · боль в колене перед полумарафоном',\n    pain:'Оставил заявку на консультацию по колену вечером в четверг, обратный звонок клиники не пришёл в срок.',\n    outcome:'g', outcomeLabel:'Играбельный пример',\n    steps:[\n      {t:'День 0', chans:[['human','Сайт']], msg:'Заполнил форму: «тянет с внешней стороны колена третий день, готовлюсь к полумарафону».', why:'Контекст «полумарафон» — ключевая деталь для всех следующих сообщений.'},\n      {t:'День 3', chans:[['human','Тишина']], msg:'Обратный звонок клиники так и не поступил — внутренний затык.', why:'Именно здесь обычно и должна подключаться связка из нескольких каналов вместо ожидания одного звонка.'},\n      {t:'День 3, 09:10', chans:[['sms','SMS'],['tg','Telegram']], msg:'Волна 1, одновременно: «Ваш вопрос по колену не потерялся — за него отвечает врач Анна Ковалёва. Слот сегодня в 18:40?»', why:'Имя врача и конкретное время — сразу в двух каналах, там, где обычно шлют одно формальное «мы вас ждём».'},\n      {t:'Дальше — развилки', chans:[], msg:'Полная версия с 4 вариантами выбора и разными концовками — ниже, в разделе «Мини-игра».', why:''},\n    ]\n  },\n  {\n    id:'fitness', niche:'Фитнес-клуб', avatar:'АР', name:'Анна Реброва, 29', who:'Клиентка · «FitZona» · пробная тренировка',\n    pain:'Записалась на пробное занятие во вторник в 19:00 и не пришла.',\n    outcome:'g', outcomeLabel:'Перенесла и пришла',\n    steps:[\n      {t:'День 0, вечер', chans:[['human','No-show']], msg:'Не пришла на пробное, тренер отметил в CRM.', why:'Триггер для волны — не молчание в переписке, а сорванная запись.'},\n      {t:'День 0, 21:30', chans:[['tg','Telegram'],['email','Email']], msg:'Волна 1, одновременно: «Всё ок? Слот на пробную остался открыт — перенести?» в Telegram + подборка «почему новичкам заходит именно утренняя группа» с двумя свободными слотами на почту.', why:'Без упрёка «вы не пришли» — сразу предложение решения в двух форматах: коротком и подробном.'},\n      {t:'День 0, 21:50', chans:[['human','Реакция']], msg:'Ответила в Telegram: «давайте в субботу утром» — хотя предложение с расписанием пришло по почте.', why:'Ответила не в тот канал, откуда пришла подробность — связка должна уметь принять ответ в любом из своих каналов.'},\n    ]\n  },\n  {\n    id:'edtech', niche:'Онлайн-школа', avatar:'ПГ', name:'Павел Гущин, 33', who:'Клиент · «Skill Lab» · вебинар «Аналитика для маркетологов»',\n    pain:'Досмотрел вебинар на 80%, не купил поток.',\n    outcome:'g', outcomeLabel:'Купил в последний день скидки',\n    steps:[\n      {t:'День 0', chans:[['human','Вебинар']], msg:'Досмотрел до 80%, задавал вопросы про Power BI в чате, оффер не кликнул.', why:'Вопросы в чате — источник персонализации для следующей волны.'},\n      {t:'День 1', chans:[['tg','Telegram'],['email','Email']], msg:'Волна 1, одновременно: короткое напоминание про старт 14 октября в Telegram + письмо «судя по вопросам про Power BI, вам подойдёт модуль «Дашборды на практике»» с программой.', why:'Лёгкое касание и персональная рекомендация идут вместе, а не по очереди с разрывом в дни.'},\n      {t:'День 4', chans:[['tg','Telegram'],['sms','SMS']], msg:'Волна 2, тишина 3 дня — связка повторяется с новым поводом: «Поток стартует через 3 дня. Для тех, кто был на вебинаре — −15% до пятницы, 2 места».', why:'Стимул и дедлайн появляются только на второй волне, не в первом касании.'},\n      {t:'День 4, вечер', chans:[['human','Итог']], msg:'Купил по SMS-ссылке в последний день скидки.', why:'Сработала комбинация конкретного дедлайна и того, что сообщение пришло сразу в двух местах.'},\n    ]\n  },\n  {\n    id:'auto', niche:'Автосервис', avatar:'ОК', name:'Олег Крайнов, 52', who:'Клиент · «АвтоDoctor» · диагностика подвески',\n    pain:'Оставил заявку «стучит подвеска», время визита не выбрал.',\n    outcome:'g', outcomeLabel:'Подтвердил по SMS',\n    steps:[\n      {t:'День 0, вечер', chans:[['tg','Telegram'],['human','Звонок']], msg:'Волна 1, одновременно: бот сервиса пишет в Telegram «какой день удобен — вторник или четверг?», параллельно менеджер пробует дозвониться — не берёт трубку за рулём.', why:'Оба канала запущены сразу — сработает тот, что окажется удобным в моменте, без ожидания, пока прогорит один способ.'},\n      {t:'День 2', chans:[['sms','SMS'],['tg','Telegram']], msg:'Волна 2, та же связка повторяется: «Ближайший слот на диагностику — завтра 10:00, бесплатно при ремонте у нас. Подтвердить?»', why:'SMS требует одного слова в ответ — удобно, когда неудобно разговаривать, а Telegram дублирует на случай, если SMS не открыл.'},\n      {t:'День 2', chans:[['human','Итог']], msg:'Ответил SMS: «давайте».', why:'Связка выбрана под контекст «за рулём», а не по умолчанию.'},\n    ]\n  },\n  {\n    id:'beauty', niche:'Салон красоты', avatar:'МЛ', name:'Мария Лунёва, 26', who:'Клиентка · «Barber&Co» · окрашивание у мастера Ксении',\n    pain:'Смотрела прайс и портфолио мастера, добавила в избранное, не записалась.',\n    outcome:'g', outcomeLabel:'Записалась',\n    steps:[\n      {t:'День 1', chans:[['vk','VK'],['tg','Telegram']], msg:'Волна 1, одновременно: «У Ксении освободилось окно в четверг 15:00 — придержать для вас?» — во VK, где она подписана на сообщество, и коротким дублем в Telegram.', why:'Одна и та же связка каналов сразу, чтобы не зависеть от того, куда она чаще заходит именно сегодня.'},\n      {t:'День 2', chans:[['vk','VK'],['tg','Telegram']], msg:'Волна 2, тот же дуэт повторяется: «Окно у Ксении ещё свободно, но на него уже есть вопрос — подтвердите бронь до вечера?»', why:'Мягкое ощущение очереди вместо агрессивного «успейте», причём в тех же двух каналах, что и в первый раз.'},\n      {t:'День 2', chans:[['human','Итог']], msg:'Записалась.', why:'Сработали два фактора вместе: живая связка каналов и лёгкое чувство дефицита слота.'},\n    ]\n  },\n  {\n    id:'realty', niche:'Недвижимость', avatar:'ВЕ', name:'Виктория Есина, 38', who:'Клиентка · «Метр Квадратный» · подбор 2-комнатной квартиры',\n    pain:'После первой подборки вариантов перестала отвечать.',\n    outcome:'a', outcomeLabel:'Переведена в редкую рассылку',\n    steps:[\n      {t:'День 0', chans:[['tg','Telegram']], msg:'Прислали 5 вариантов по её критериям.', why:'Первый контакт ещё точечный — связка из нескольких каналов включается только при тишине.'},\n      {t:'День 4', chans:[['email','Email'],['tg','Telegram']], msg:'Волна 1, одновременно: новый вариант с террасой в бюджете с видео-обзором на почту + короткое Telegram-напоминание о нём в тот же день.', why:'ИИ дождался нового релевантного объекта, а не просто повторил напоминание о старых, и сразу отправил его в двух местах.'},\n      {t:'День 9', chans:[['sms','SMS'],['email','Email']], msg:'Волна 2, тишина ещё 5 дней — связка повторяется с бо́льшей срочностью: «Нашли вариант с террасой в вашем бюджете — уходит быстро, посмотреть сегодня?»', why:'Тот же принцип: две волны с одинаковой парой каналов, но более настойчивым поводом на второй.'},\n      {t:'День 14', chans:[['human','Итог']], msg:'Не ответила ни разу за две недели ни на одну волну — новые волны остановлены, клиентка переведена в редкую ежемесячную рассылку.', why:'Важная часть логики: связка каналов должна уметь вовремя остановиться, а не давить бесконечно.'},\n    ]\n  },\n  {\n    id:'saas', niche:'B2B SaaS', avatar:'ИМ', name:'Игорь Матвеев', who:'Клиент · «CRM Volna» · демо интеграции с 1С',\n    pain:'Забронировал демо-звонок и не пришёл на созвон.',\n    outcome:'g', outcomeLabel:'Follow-up назначен точно по его сроку',\n    steps:[\n      {t:'+20 минут', chans:[['email','Email'],['tg','Telegram']], msg:'Волна 1, одновременно: письмо «видим, что не получилось созвониться — вот 4-минутное видео с ответом на ваш запрос про 1С, и два новых слота» + короткое Telegram-сообщение с тем же предложением, потому что при регистрации на демо он указал мессенджер как предпочтительный контакт.', why:'Реакция на no-show мгновенная и сразу в двух каналах, но без упрёка.'},\n      {t:'День 2', chans:[['human','Итог']], msg:'Ответил в Telegram: «да, но через 2 недели — сейчас отчётный период».', why:'Follow-up ставится ровно на названный клиентом срок, а не на стандартный цикл в 3 дня — обе волны при этом держатся наготове на тот случай, если он напишет раньше.'},\n    ]\n  },\n  {\n    id:'ecom', niche:'E-commerce', avatar:'КО', name:'Кристина Орлова, 24', who:'Клиентка · «GlowBox» · брошенная корзина на 3 200 ₽',\n    pain:'Добавила 3 товара в корзину поздно вечером и ушла с этапа оплаты.',\n    outcome:'g', outcomeLabel:'Купила по SMS-промокоду',\n    steps:[\n      {t:'День 1, 12:30', chans:[['tg','Telegram'],['email','Email']], msg:'Волна 1, одновременно: «Сыворотка из вашей корзины + бесплатная доставка сегодня» в Telegram и то же предложение письмом.', why:'Конкретный товар из её же корзины сразу в двух каналах, а не общее «загляните к нам» в одном.'},\n      {t:'День 2', chans:[['sms','SMS'],['vk','VK']], msg:'Волна 2, тишина ещё день — связка меняется на SMS и ретаргетинг во VK: промокод −10% на 24 часа.', why:'Скидка появляется только на второй волне — иначе покупатели привыкают всегда её ждать.'},\n      {t:'День 2, вечер', chans:[['human','Итог']], msg:'Купила по ссылке из SMS.', why:'Сработала связка «персональный контекст на первой волне + ограниченный по времени стимул на второй», а не скидка сразу в первом сообщении.'},\n    ]\n  },\n];\n\nlet activeCjm = CJM[0].id;\n\nfunction renderCjmTabs(){\n  const tabs = document.getElementById('cjmTabs');\n  tabs.innerHTML = CJM.map(c => `\n    <button data-id=\"${c.id}\" class=\"${c.id===activeCjm?'on':''}\">${c.niche}<small>${c.name}</small></button>\n  `).join('');\n  tabs.querySelectorAll('button').forEach(btn => {\n    btn.addEventListener('click', () => { activeCjm = btn.dataset.id; renderCjmTabs(); renderCjmPane(); });\n  });\n}\n\nfunction renderCjmPane(){\n  const c = CJM.find(x => x.id === activeCjm);\n  const pane = document.getElementById('cjmPane');\n  const outBadge = c.outcome === 'g' ? 'g' : c.outcome === 'a' ? 'a' : 'r';\n  pane.innerHTML = `\n    <div class=\"cjm-head\">\n      <div class=\"cjm-avatar\">${c.avatar}</div>\n      <div>\n        <h3>${c.name}</h3>\n        <div class=\"who\">${c.who}</div>\n        <div class=\"pain\">${c.pain}</div>\n      </div>\n      <div class=\"cjm-outcome\"><span class=\"badge ${outBadge}\">${c.outcomeLabel}</span></div>\n    </div>\n    <div class=\"timeline\">\n      ${c.steps.map(s => `\n        <div class=\"tl-step\">\n          <div class=\"t\">${s.t}</div>\n          <div class=\"tl-dot-col\"><div class=\"tl-dot\"></div><div class=\"tl-line\"></div></div>\n          <div class=\"tl-body\">\n            <div class=\"row1\">${(s.chans||[]).map(([chan,label]) => `<span class=\"chan ${chan}\"><i></i>${label}</span>`).join('')}</div>\n            <div class=\"msg\">${s.msg}</div>\n            ${s.why ? `<div class=\"why\">${s.why}</div>` : ''}\n          </div>\n        </div>`).join('')}\n    </div>\n  `;\n}\n\n/* ===================== ПЛЮСЫ / МИНУСЫ ===================== */\nconst PC = [\n  {\n    title:'Разовые напоминания', sub:'сотрудник вручную вспомнил и написал клиенту',\n    plus:['Не требует настройки и бюджета на инструменты','Гибко — можно учесть любой контекст на лету, живой тон','Хорошо для VIP-сделок, где важен личный контакт'],\n    minus:['Не масштабируется — держится на памяти и добросовестности конкретного человека','Нет данных о том, что сработало, а что нет','Клиенты проваливаются в загруженные дни'],\n  },\n  {\n    title:'Системные напоминания', sub:'по расписанию, всем клиентам один и тот же текст', mid:true,\n    plus:['Работает без участия человека, масштабируется на любой объём','Предсказуемо — легко тестировать и мерить','Физически не пропускает клиентов'],\n    minus:['Одинаковый текст всем — не учитывает контекст конкретного клиента','Может писать в неудобное время неудобным каналом','При частой отправке — отписки и жалобы на спам'],\n  },\n  {\n    title:'ИИ-напоминания', sub:'момент, текст и связка каналов — под конкретного клиента',\n    plus:['Подбирает момент, формулировку и связку каналов под историю клиента','Несколько волн вместо одного захода — конверсия выше при том же числе касаний','Использует поведенческие данные без участия человека'],\n    minus:['Дороже и сложнее в настройке — нужны интеграции, данные, бюджет на LLM','Без нормальных правил может написать что-то неуместное или навязчивое','На холодной базе без истории работает не лучше системных'],\n  },\n];\n\nfunction renderPC(){\n  const grid = document.getElementById('pcGrid');\n  grid.innerHTML = PC.map(p => `\n    <div class=\"card card-pad pc-card ${p.mid?'mid':''}\">\n      <h3>${p.title}</h3>\n      <div class=\"sub\">${p.sub}</div>\n      <ul class=\"pc-list plus\">${p.plus.map(x => `<li><i>+</i>${x}</li>`).join('')}</ul>\n      <ul class=\"pc-list minus\">${p.minus.map(x => `<li><i>−</i>${x}</li>`).join('')}</ul>\n    </div>`).join('');\n}\n\n/* ===================== ТРЕНДЫ ===================== */\nconst TRENDS_RU = [\n  '<b>Мессенджеры обгоняют email по открываемости.</b> Email в РФ чаще держится на B2B и транзакционных письмах, реактивацию тянут Telegram и VK.',\n  '<b>SMS — тяжёлая артиллерия, не первый шаг.</b> Открываемость выше всех остальных каналов, но и цена за сообщение выше — чаще ставят в связку на финальной волне, а не в первое касание.',\n  '<b>Ужесточение по 152-ФЗ и антиспам-политике площадок.</b> Explicit opt-in обязателен, жалобы на рассылку легко приводят к блокировке бота или аккаунта.',\n  '<b>Max как обязательный дополнительный канал.</b> Часть аудитории системно переезжает в мессенджер — интеграция пока только через вебхуки и сторонние сервисы.',\n  '<b>RCS не прижился.</b> В отличие от западных рынков, богатые SMS с кнопками и медиа у операторов не заработали — SMS остаётся простым текстом.',\n  '<b>Ставка на «живой» тон.</b> От руки менеджера, с именем и умеренными эмодзи — заходит лучше, чем формальный рассылочный стиль.',\n];\nconst TRENDS_INTL = [\n  '<b>Send-time optimization как стандарт.</b> Крупные CRM-платформы (Braze, Klaviyo, Iterable) отправляют не по фиксированному времени, а по предсказанному «лучшему часу» для каждого пользователя.',\n  '<b>WhatsApp Business API — основной канал реактивации</b> в Европе и Латинской Америке; в РФ канал недоступен по бизнес-API, отсюда и его отсутствие в этом стеке.',\n  '<b>RCS Business Messaging растёт.</b> После поддержки в iOS SMS постепенно превращаются в интерактивные сообщения с кнопками и карточками.',\n  '<b>Динамический контент от ИИ на уровне платформы.</b> Klaviyo AI, HubSpot Breeze и подобные сами генерируют варианты текста и подборки товаров под конкретного получателя.',\n  '<b>Жёсткое регулирование частоты.</b> GDPR, CAN-SPAM и TCPA для SMS — не только этика, а юридическое требование к ограничению частоты касаний.',\n  '<b>«Message fatigue» как признанная проблема.</b> Общий сдвиг индустрии от плоских drip-цепочек к связкам из нескольких каналов сразу: меньше отдельных сообщений, точнее момент и повод для каждой волны.',\n];\n\nfunction renderTrends(){\n  document.getElementById('trendRu').innerHTML = TRENDS_RU.map(t => `<li>${t}</li>`).join('');\n  document.getElementById('trendIntl').innerHTML = TRENDS_INTL.map(t => `<li>${t}</li>`).join('');\n}\n\n/* ===================== МИНИ-ИГРА ===================== */\n/* Граф из 20 узлов: 9 сюжетных, 3 развязочных, 8 концовок. */\nconst GAME = {\n  s1: {\n    heat:40, meta:'Четверг, 21:40 · сайт клиники',\n    text:'Дмитрий гуглит «болит колено после бега», попадает на сайт «ДвижениеPRO», читает статью про травмы колена и заполняет короткую форму: имя, телефон и поле «что беспокоит» — «тянет с внешней стороны колена третий день, готовлюсь к полумарафону».',\n    next:'s2'\n  },\n  s2: {\n    heat:45, meta:'Четверг, 21:41 · Telegram-бот клиники',\n    text:'ИИ ставит заявку в очередь и сразу отправляет подтверждение в Telegram (Дмитрий давал согласие на бота при записи в беговой клуб при клинике).',\n    msg:'«Дмитрий, заявка принята! Врач перезвонит в течение рабочего дня. И это нормально, что вы уже гуглите — небольшая боль в колене за 3 недели до старта встречается часто».',\n    next:'s3'\n  },\n  s3: {\n    heat:35, meta:'Пятница, весь день · тишина от клиники',\n    text:'Проходит пятница — никто так и не позвонил: у клиники в этот день не хватило свободного администратора. Что делает Дмитрий?',\n    choices:[\n      {letter:'A', label:'Сам звонит в клинику уточнить статус заявки', reaction:'Дозвонился с третьей попытки, администратор извинился и сразу записал на понедельник, 11:00.', next:'humanRescue', heatDelta:+20},\n      {letter:'B', label:'Ничего не делает, просто ждёт звонка', reaction:'Заодно на всякий случай открывает сайт другой клиники — но вкладку не закрывает, продолжает ждать.', next:'s4', heatDelta:-10},\n      {letter:'C', label:'Ищет альтернативную клинику «на всякий случай»', reaction:'Находит похожее предложение у конкурента, сохраняет ссылку — пока не пишет им.', next:'s4', heatDelta:-15},\n      {letter:'D', label:'Раздражённо отписывается от Telegram-бота клиники', reaction:'Пишет «неважно, обращусь в другое место» и блокирует бота.', next:'E_lostAngry', heatDelta:-40},\n    ]\n  },\n  s4: {\n    heat:30, meta:'Понедельник, 09:05 · первая волна',\n    text:'CRM видит: заявка 3 дня без движения, обратный звонок так и не поступил. Модуль эскалации не ждёт ещё один звонок, а сразу запускает связку из двух каналов одновременно — SMS и Telegram, с одним и тем же предложением.',\n    msg:'SMS + Telegram, 09:10: «Дмитрий, ваш вопрос по колену не потерялся — за него отвечает врач Анна Ковалёва. Запишем на сегодня 18:40 или на любое время на этой неделе?»',\n    next:'s5'\n  },\n  s5: {\n    heat:null, meta:'Понедельник, реакция на волну SMS + Telegram',\n    text:'Что делает Дмитрий, получив оба сообщения?',\n    choices:[\n      {letter:'A', label:'Сразу отвечает: «да, 18:40 подходит»', reaction:'Ответ ушёл автоматически, слот закреплён.', next:'E_fast', heatDelta:+30},\n      {letter:'B', label:'Читает оба и не отвечает — неудобно посреди рабочего дня', reaction:'Оба сообщения прочитаны, статус в CRM — «тёплый, без ответа».', next:'s6', heatDelta:0},\n      {letter:'C', label:'Отвечает «СТОП, не пишите мне больше»', reaction:'Автоматика мгновенно останавливает все дальнейшие сообщения по этому клиенту в обоих каналах.', next:'E_optout', heatDelta:-30},\n      {letter:'D', label:'Отвечает в Telegram: «а сколько стоит консультация?»', reaction:'Бот сразу присылает цену и добавляет: «первичная диагностика входит в стоимость приёма».', next:'s6', heatDelta:+10},\n    ]\n  },\n  s6: {\n    heat:25, meta:'Четверг, 08:15 · вторая волна',\n    text:'Проходят вторник и среда. ИИ видит: Дмитрий кликал по статье «как быстро восстановиться после травмы колена бегуну» на сайте клиники — значит боль не прошла, а тревога, скорее всего, выросла. Связка каналов повторяется, но добавляется email — для спокойного, развёрнутого сообщения без давления.',\n    msg:'Email + Telegram, одновременно: «Дмитрий, слот у Анны Ковалёвой на завтра в 11:00 всё ещё свободен» — в письме с именем врача, её специализацией по спортивным травмам и прямой ссылкой на бронь, в Telegram — короткий дубль с той же ссылкой.',\n    next:'s7'\n  },\n  s7: {\n    heat:null, meta:'Четверг, реакция на email + Telegram',\n    text:'Что делает Дмитрий с этими сообщениями?',\n    choices:[\n      {letter:'A', label:'Открывает письмо и сразу бронирует слот по ссылке', reaction:'Бронь на завтра, 11:00, подтверждена автоматически.', next:'E_email', heatDelta:+30},\n      {letter:'B', label:'Открывает оба, читает, закрывает — «может, само пройдёт»', reaction:'Оба сообщения прочитаны полностью, действий не последовало.', next:'s9', heatDelta:-5},\n      {letter:'C', label:'Не открывает письмо, Telegram пролистывает не глядя', reaction:'Оба сообщения остаются непрочитанными по-настоящему пять дней подряд.', next:'s9', heatDelta:-10},\n      {letter:'D', label:'Пишет в Telegram: «а можно на следующей неделе, сейчас запара на работе?»', reaction:'Бот сразу фиксирует гибкий слот на следующей неделе и присылает подтверждение в обоих каналах.', next:'reschedule', heatDelta:+15},\n    ]\n  },\n  s9: {\n    heat:18, meta:'Суббота · день 6 после заявки, третья волна',\n    text:'До полумарафона остаётся 2 недели, тревога у Дмитрия объективно должна расти, но он «терпит». ИИ переходит на финальную волну: раз обычные напоминания и персональные слоты не сработали, добавляется стимул — бесплатная диагностика вместо прямой скидки — и связка снова меняется на Telegram + SMS, более заметную в выходной день.',\n    msg:'Telegram + SMS, воскресенье, 12:00: «Дмитрий, если запишетесь на этой неделе — диагностика на месте бесплатно, обычно это отдельная услуга. Врач Анна Ковалёва свободна во вторник и среду».',\n    next:'s10'\n  },\n  s10: {\n    heat:null, meta:'Воскресенье, финальная реакция',\n    text:'Финальная волна — что решает Дмитрий?',\n    choices:[\n      {letter:'A', label:'Записывается на бесплатную диагностику', reaction:'Выбирает вторник, бронь подтверждена.', next:'E_incentive', heatDelta:+25},\n      {letter:'B', label:'Всё ещё не отвечает — «после старта разберусь»', reaction:'Полумарафон проходит, колено болит сильнее, но заявка в клинику так и не доведена до записи.', next:'E_lostSilent', heatDelta:-30},\n      {letter:'C', label:'Отвечает с сомнением: «а если серьёзно, вы что, просто так МРТ будете делать?»', reaction:'Система помечает клиента флагом «недоверие к предложению» и передаёт живому врачу.', next:'trustCall', heatDelta:+5},\n    ]\n  },\n\n  humanRescue: {\n    heat:60, meta:'Понедельник, 11:00 · спасено человеком',\n    text:'Администратор лично записал Дмитрия на консультацию. Волны от ИИ так и не понадобились — сработала удача и настойчивость самого клиента.',\n    next:'E_human'\n  },\n  reschedule: {\n    heat:55, meta:'Следующая неделя',\n    text:'Через неделю бот присылает короткое напоминание о перенесённой брони — Дмитрий приходит на приём.',\n    next:'E_later'\n  },\n  trustCall: {\n    heat:50, meta:'Понедельник, звонок врача',\n    text:'Анна Ковалёва лично звонит Дмитрию: «Это не акция ради галочки — при боли в колене перед стартом важно быстро увидеть картинку, чтобы не усугубить травму». Дмитрий соглашается на диагностику.',\n    next:'E_trustSaved'\n  },\n\n  E_human: { end:true, kind:'mid', heat:60, title:'Записался — но благодаря удаче, а не системе',\n    text:'Дмитрий дошёл до консультации, но только потому, что сам проявил настойчивость и дозвонился. Если бы он в тот момент устал ждать и просто закрыл вкладку — заявка осталась бы висеть без движения.',\n    lesson:'Вывод: без волн от ИИ воронка держится на добросовестности конкретного администратора и удаче самого клиента, а не на системе.' },\n  E_fast: { end:true, kind:'good', heat:90, title:'Быстрая запись — связка SMS + Telegram сработала с первого раза',\n    text:'Персональное сообщение с именем врача и конкретным временем убрало главное препятствие: неизвестность. Дмитрий ответил в течение минуты.',\n    lesson:'Вывод: конкретика (имя врача + время) снимает тревогу лучше, чем формальное «мы вас ждём».' },\n  E_optout: { end:true, kind:'mid', heat:0, title:'Отписался — и это правильно обработанный отказ',\n    text:'Дмитрий явно попросил прекратить общение. ИИ мгновенно остановил все дальнейшие сообщения по этому клиенту в обоих каналах.',\n    lesson:'Вывод: клиент потерян, но без репутационного вреда — уважение к явному отказу важнее ещё одной попытки достучаться.' },\n  E_email: { end:true, kind:'good', heat:85, title:'Записался после email — сработало добавление канала',\n    text:'После связки SMS + Telegram без ответа письмо с именем врача и прямой ссылкой закрыло сомнения без давления.',\n    lesson:'Вывод: добавление канала в волну — это не просто «попробовать ещё раз», а другой формат сообщения под другое эмоциональное состояние клиента.' },\n  E_later: { end:true, kind:'good', heat:70, title:'Пришёл с опозданием на неделю — но пришёл',\n    text:'Гибкость (перенос без сопротивления) удержала клиента там, где жёсткий единственный слот его бы потерял.',\n    lesson:'Вывод: волны должны уметь подстраиваться под ответ клиента, а не только давить по расписанию.' },\n  E_incentive: { end:true, kind:'good', heat:75, title:'Записался на бесплатную диагностику — сработал стимул финальной волны',\n    text:'Только на третьей волне появился стимул — и именно поэтому он не обесценил предыдущие сообщения.',\n    lesson:'Вывод: стимул, показанный в первой же волне, приучает ждать скидку всегда. На финальной волне — он спасает почти потерянного клиента.' },\n  E_trustSaved: { end:true, kind:'good', heat:65, title:'Записался после звонка врача — ИИ передал эстафету человеку',\n    text:'Система правильно распознала сигнал недоверия и передала клиента живому специалисту вместо ещё одного автоматического сообщения.',\n    lesson:'Вывод: хорошая схема с волнами умеет вовремя остановиться и подключить человека — не всё должен закрывать ИИ.' },\n  E_lostSilent: { end:true, kind:'bad', heat:10, title:'Клиент потерян — тишина победила все напоминания',\n    text:'Ни одна из трёх волн и связок каналов не пробила стену «само пройдёт». Неделю спустя Дмитрий гуглит уже другую клинику.',\n    lesson:'Вывод: даже хорошая схема с волнами не гарантирует конверсию — но минимизирует число таких случаев, а не отменяет их полностью.' },\n  E_lostAngry: { end:true, kind:'bad', heat:0, title:'Клиент потерян и раздражён — слишком рано, слишком настойчиво',\n    text:'Дмитрий отписался после первой же паузы в общении со стороны клиники, ещё до того, как включились волны от ИИ.',\n    lesson:'Вывод: даже отличная схема с волнами не спасает, если первый человеческий этап (звонок за 1 день) уже подвёл ожидания.' },\n};\n\nlet gameState = { node:'s1', heat:40, path:[], history:[] };\n\nfunction heatWord(h){\n  if (h === null) return { word:'—', color:'var(--ink-3)' };\n  if (h >= 70) return { word:'Готов купить', color:'var(--good)' };\n  if (h >= 40) return { word:'Тёплый, думает', color:'var(--warn)' };\n  return { word:'Остывает', color:'var(--bad)' };\n}\n\nfunction renderGame(){\n  const node = GAME[gameState.node];\n  const scene = document.getElementById('gameScene');\n  const heat = gameState.heat;\n  const hw = heatWord(heat);\n  document.getElementById('heatBar').style.width = Math.max(4, heat) + '%';\n  document.getElementById('heatBar').style.background = hw.color;\n  document.getElementById('heatWord').textContent = hw.word;\n  document.getElementById('heatWord').style.color = hw.color;\n  document.getElementById('stepCount').textContent = gameState.path.length;\n  document.getElementById('stepDots').innerHTML = Array.from({length:20}).map((_,i) =>\n    `<i class=\"${i < gameState.path.length ? 'done' : ''}\"></i>`).join('');\n\n  if (node.end){\n    scene.innerHTML = `\n      <div class=\"ending-banner ${node.kind}\">\n        <h4>${node.title}</h4>\n        <p>${node.text}</p>\n        <div class=\"lesson\">${node.lesson}</div>\n      </div>\n      <div class=\"game-next\"><button id=\"againBtn\">Пройти другой вариант</button></div>\n    `;\n    document.getElementById('againBtn').addEventListener('click', resetGame);\n    return;\n  }\n\n  let html = `<div class=\"meta\"><span class=\"game-meta-tag\">${node.meta}</span></div><p>${node.text}</p>`;\n  if (node.msg) html += `<div class=\"msgbox game-msg\">${node.msg}</div>`;\n\n  if (node.choices){\n    html += `<div class=\"game-choices\">` + node.choices.map((c,i) => `\n      <button class=\"choice-btn\" data-i=\"${i}\"><span class=\"letter\">${c.letter}</span><span>${c.label}</span></button>\n    `).join('') + `</div>`;\n  } else {\n    html += `<div class=\"game-next\"><button id=\"nextBtn\">Далее →</button></div>`;\n  }\n  scene.innerHTML = html;\n\n  if (node.choices){\n    scene.querySelectorAll('.choice-btn').forEach(btn => {\n      btn.addEventListener('click', () => {\n        const choice = node.choices[+btn.dataset.i];\n        gameState.path.push(gameState.node);\n        if (choice.heatDelta) gameState.heat = Math.max(0, Math.min(100, gameState.heat + choice.heatDelta));\n        scene.innerHTML = `<div class=\"meta\"><span class=\"game-meta-tag\">${node.meta}</span></div><p>${node.text}</p>\n          ${node.msg ? `<div class=\"msgbox game-msg\">${node.msg}</div>` : ''}\n          <div class=\"reaction-box\"><b>Дмитрий выбирает: ${choice.label}.</b><br>${choice.reaction}</div>\n          <div class=\"game-next\"><button id=\"continueBtn\">Далее →</button></div>`;\n        document.getElementById('continueBtn').addEventListener('click', () => {\n          gameState.node = choice.next;\n          const nextNode = GAME[gameState.node];\n          if (nextNode.heat !== null && nextNode.heat !== undefined) gameState.heat = nextNode.heat;\n          renderGame();\n        });\n      });\n    });\n  } else {\n    document.getElementById('nextBtn').addEventListener('click', () => {\n      gameState.path.push(gameState.node);\n      gameState.node = node.next;\n      const nextNode = GAME[gameState.node];\n      if (nextNode.heat !== null && nextNode.heat !== undefined) gameState.heat = nextNode.heat;\n      renderGame();\n    });\n  }\n}\n\nfunction resetGame(){\n  gameState = { node:'s1', heat:40, path:[], history:[] };\n  renderGame();\n}\n\ndocument.getElementById('restartBtn').addEventListener('click', resetGame);\n\n/* ===================== INIT ===================== */\nrenderChannels();\nrenderCascade();\nrenderWhyAi();\nrenderCjmTabs();\nrenderCjmPane();\nrenderPC();\nrenderTrends();\nrenderGame();\n</script>\n</body>\n</html>\n";
